  ('20260815-0001-0000-0000-000000000059', v_mazda_id, v_device_id, '2026-08-15 08:00:00+07', '2026-08-15 08:45:00+07', 2431.0, 2455.0, 24.0, 2700, 32.0, 50.0, 21.3050, 105.3850, 21.3280, 105.4150, 'Nhà|Đi lại cuối tuần', 'COMPLETED'),
  ('20260816-0001-0000-0000-000000000060', v_mazda_id, v_device_id, '2026-08-16 07:30:00+07', '2026-08-16 09:30:00+07', 2455.0, 2539.0, 84.0, 7200, 42.0, 65.0, 21.3050, 105.3850, 21.2500, 105.5200, 'Nhà|Về 2 quê', 'COMPLETED'),
  ('20260818-0001-0000-0000-000000000061', v_mazda_id, v_device_id, '2026-08-18 08:30:00+07', '2026-08-18 09:10:00+07', 2539.0, 2557.0, 18.0, 2400, 27.0, 45.0, 21.3050, 105.3850, 21.3200, 105.4050, 'Nhà|Đi việc cá nhân', 'COMPLETED'),
  ('20260820-0001-0000-0000-000000000062', v_mazda_id, v_device_id, '2026-08-20 08:00:00+07', '2026-08-20 08:45:00+07', 2557.0, 2582.0, 25.0, 2700, 33.3, 50.0, 21.3050, 105.3850, 21.3300, 105.4150, 'Nhà|Đi lại sinh hoạt', 'COMPLETED'),
  ('20260822-0001-0000-0000-000000000063', v_mazda_id, v_device_id, '2026-08-22 08:00:00+07', '2026-08-22 08:40:00+07', 2582.0, 2603.0, 21.0, 2400, 31.5, 48.0, 21.3050, 105.3850, 21.3250, 105.4100, 'Nhà|Đi lại trước chuyến về quê', 'COMPLETED'),
  ('20260823-0001-0000-0000-000000000064', v_mazda_id, v_device_id, '2026-08-23 07:30:00+07', '2026-08-23 09:30:00+07', 2603.0, 2651.0, 48.0, 7200, 40.0, 65.0, 21.3050, 105.3850, 21.2500, 105.5200, 'Nhà|Về 2 quê (Chốt sổ tay 2.651 km)', 'COMPLETED')
  ON CONFLICT (id) DO UPDATE SET 
    distance_km = EXCLUDED.distance_km,
    start_odometer = EXCLUDED.start_odometer,
    end_odometer = EXCLUDED.end_odometer,
    notes = EXCLUDED.notes;

  -- 5. XÓA CÁC CHUYẾN TRÔI GPS ĐỨNG YÊN (< 200m) GIAI ĐOẠN OBD (TỪ 24/08 ĐẾN NAY)
  DELETE FROM public.trips
  WHERE asset_id = v_mazda_id
    AND start_time >= '2026-08-24'
    AND (distance_km < 0.2 OR distance_km IS NULL);

  -- 6. TÍNH TỔNG QUÃNG ĐƯỜNG ĐANG CÓ CỦA CÁC CHUYẾN OBD (TỪ 24/08)
  SELECT COALESCE(SUM(distance_km), 0)
  INTO v_obd_sum
  FROM public.trips
  WHERE asset_id = v_mazda_id
    AND start_time >= '2026-08-24';

  -- 7. CÂN CHỈNH TỶ LỆ CÁC CHUYẾN OBD ĐỂ TỔNG ĐẠT ĐÚNG 329,00 KM (2.651 km -> 2.980 km)
  IF v_obd_sum > 0 THEN
    v_scale := v_target_obd_dist / v_obd_sum;
  END IF;

  FOR v_trip IN
    SELECT id, distance_km
    FROM public.trips
    WHERE asset_id = v_mazda_id
      AND start_time >= '2026-08-24'
    ORDER BY start_time ASC
  LOOP
    UPDATE public.trips
    SET 
      distance_km = ROUND((v_trip.distance_km * v_scale)::numeric, 2),
      start_odometer = ROUND(v_running_odo::numeric, 2),
      end_odometer = ROUND((v_running_odo + (v_trip.distance_km * v_scale))::numeric, 2)
    WHERE id = v_trip.id;

    v_running_odo := v_running_odo + (v_trip.distance_km * v_scale);
  END LOOP;

  -- 8. CHỐT CHẶNG CUỐI CÙNG ĐÚNG CHÍNH XÁC MỐC 2.980,00 KM
  UPDATE public.trips
  SET end_odometer = 2980.0
  WHERE id = (
    SELECT id FROM public.trips 
    WHERE asset_id = v_mazda_id 
    ORDER BY start_time DESC LIMIT 1
  );

  -- 9. CẬP NHẬT CHUẨN ODOMETER TRONG BẢNG ASSETS LÊN 2.980 KM
  UPDATE public.assets
  SET 
    current_odometer_km = 2980,
    virtual_odometer_km = 2980,
    initial_odometer_km = 12,
    updated_at = NOW()
  WHERE id = v_mazda_id;

  RAISE NOTICE 'Đã cân chỉnh hoàn tất toàn bộ chuyến đi! Tổng km các chuyến = ODO xe = 2.980 KM!';
END $$;

